class Solution {
public:
    bool isThereAPath(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        int total_len = m + n - 1;
        if (total_len % 2 == 1) return false;
        int target = total_len / 2;
        std::vector<std::bitset<205>> dp(n);
        dp[0].set(grid[0][0]);
        for (int c = 1; c < n; ++c) {
            dp[c] = dp[c - 1] << grid[0][c];
        }
        for (int r = 1; r < m; ++r) {
            dp[0] = dp[0] << grid[r][0];
            for (int c = 1; c < n; ++c) {
                dp[c] = (dp[c] | dp[c - 1]) << grid[r][c];
            }
        }
        return dp[n - 1].test(target);
    }
};

class Solution {
    public boolean isThereAPath(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int totalLen = m + n - 1;
        if (totalLen % 2 == 1) return false;
        int target = totalLen / 2;
        java.math.BigInteger[] dp = new java.math.BigInteger[n];
        dp[0] = java.math.BigInteger.ONE.shiftLeft(grid[0][0]);
        for (int c = 1; c < n; c++) {
            dp[c] = dp[c - 1].shiftLeft(grid[0][c]);
        }
        for (int r = 1; r < m; r++) {
            dp[0] = dp[0].shiftLeft(grid[r][0]);
            for (int c = 1; c < n; c++) {
                dp[c] = dp[c].or(dp[c - 1]).shiftLeft(grid[r][c]);
            }
        }
        return dp[n - 1].testBit(target);
    }
}

var isThereAPath = function(grid) {
    const m = grid.length, n = grid[0].length;
    const totalLen = m + n - 1;
    if (totalLen % 2 === 1) return false;
    const target = BigInt(Math.floor(totalLen / 2));
    const dp = new Array(n);
    dp[0] = 1n << BigInt(grid[0][0]);
    for (let c = 1; c < n; c++) {
        dp[c] = dp[c - 1] << BigInt(grid[0][c]);
    }
    for (let r = 1; r < m; r++) {
        dp[0] = dp[0] << BigInt(grid[r][0]);
        for (let c = 1; c < n; c++) {
            dp[c] = (dp[c] | dp[c - 1]) << BigInt(grid[r][c]);
        }
    }
    return ((dp[n - 1] >> target) & 1n) === 1n;
};
